title:
// ❌ 나중에 속성 추가
const [state, setState] = useState({ id: 1 })
setState({ ...state, text: 'hello' })   // Shape 바뀜!
setState({ ...state, done: false })     // Shape 또 바뀜!

// ✅ 처음부터 완성
const [state, setState] = useState({
  id: 1,
  text: '',
  done: false,
  loading: false
})
setState({ ...state, text: 'hello' })  // Shape 그대로 ✅

