title:
// ❌ 구조가 달라지면 다른 Shape → IC 미스
todos.map(todo =>
  todo.done
    ? <TodoItem id={todo.id} text={todo.text} done={todo.done} />
    : <TodoItem id={todo.id} text={todo.text} />
    // done 없음 → 다른 Shape ❌
)

// ✅ 항상 같은 구조, 내부에서 판단
todos.map(todo => (
  <TodoItem
    key={todo.id}
    id={todo.id}
    text={todo.text}
    done={todo.done ?? false}  // 없으면 기본값
  />
))
// 같은 Shape → IC 히트 계속 ✅

